import { Component } from "@bernouy/components/base";

import { positiveInteger, setAttributeIfChanged, statusCodes, statusDefaults } from "./helpers";
import { syncPresentation, syncRenderedOffers } from "./presentation";

export class CommerceAccountOffers extends Component {
    static observedAttributes = [
        "accent-color",
        "button-accent-color",
        "button-background-color",
        "button-border-color",
        "button-text-color",
        "card-background-color",
        "card-border-color",
        "card-text-color",
        "create-label",
        "create-url",
        "edit-label",
        "edit-url",
        "price-label",
        "price-url",
        "view-label",
        "view-url",
        "empty-filtered-title",
        "empty-filtered-message",
        "empty-title",
        "empty-message",
        "error-message",
        "field-background-color",
        "field-border-color",
        "field-text-color",
        "grid-gap",
        "grid-max",
        "grid-min",
        "grid-packing",
        "card-stretch",
        "image-fit",
        "image-height",
        "locale",
        "page-param",
        "page-size",
        "source-id",
        "source-prefix",
        "status-label",
        "status-param",
        "sync-url",
        "text-color",
        ...statusCodes.map((status) => `label-${status.replaceAll("_", "-")}`),
        ...["image", "price", "status", "updated-at"].map((field) => `show-${field}`),
    ];

    constructor() {
        super({ css: ":host { display: contents; }", template: "<slot></slot>" });
        this.page = 1;
        this.status = "all";
        this.observer = null;
    }

    connectedCallback() {
        super.connectedCallback();
        this.addEventListener("change", this.onFilterChange);
        this.addEventListener("basic-pagination:change", this.onPageChange);
        const Observer = this.ownerDocument.defaultView?.MutationObserver ?? MutationObserver;
        this.observer = new Observer(() => queueMicrotask(() => this.syncRenderedOffers()));
        this.observer.observe(this, {
            childList: true,
            subtree: true,
            characterData: true,
            attributes: true,
            attributeFilter: ["data-media-id", "data-source-height", "data-source-width"],
        });
        this.readUrlState();
        this.sync();
    }

    disconnectedCallback() {
        this.removeEventListener("change", this.onFilterChange);
        this.removeEventListener("basic-pagination:change", this.onPageChange);
        this.observer?.disconnect();
        this.observer = null;
    }

    attributeChangedCallback() {
        if (this.isConnected) {
            queueMicrotask(() => this.sync());
        }
    }

    sync() {
        const pageSize = positiveInteger(this.getAttribute("page-size"), 12);
        const prefix = (this.getAttribute("source-prefix") || "/.cms/sources").replace(/\/+$/, "");
        const sourceId = encodeURIComponent(this.getAttribute("source-id") || "commerce");
        const offset = (this.page - 1) * pageSize;
        const source = `${prefix}/${sourceId}/listMyOffers?status=${encodeURIComponent(this.status)}&limit=${pageSize}&offset=${offset}`;
        setAttributeIfChanged(this.querySelector("[data-offers-source]"), "cms-source", source);

        syncPresentation(this, pageSize);
        this.syncRenderedOffers();
    }

    syncRenderedOffers() {
        syncRenderedOffers(this);
    }

    get sourceBase() {
        const prefix = (this.getAttribute("source-prefix") || "/.cms/sources").replace(/\/+$/, "");
        return `${prefix}/${encodeURIComponent(this.getAttribute("source-id") || "commerce")}`;
    }

    statusLabel(status) {
        const code = statusCodes.includes(status) ? status : "draft";
        return this.getAttribute(`label-${code.replaceAll("_", "-")}`) || statusDefaults[code];
    }

    offerAction(workflowState, publiclyVisible) {
        if (workflowState === "awaiting_seller_price") {
            return {
                label: this.getAttribute("price-label") || "Définir mon prix",
                url: this.getAttribute("price-url") || "/mon-espace/definir-prix",
            };
        }
        if (["draft", "changes_requested"].includes(workflowState)) {
            return {
                label: this.getAttribute("edit-label") || "Modifier",
                url: this.getAttribute("edit-url") || "/mon-espace/modifier-annonce",
            };
        }
        if (!publiclyVisible) {
            return null;
        }
        return {
            label: this.getAttribute("view-label") || "Voir",
            url: this.getAttribute("view-url") || this.getAttribute("edit-url") || "/mon-espace/modifier-annonce",
        };
    }

    readUrlState() {
        if (this.getAttribute("sync-url") === "false" || typeof location === "undefined") {
            return;
        }
        const params = new URLSearchParams(location.search);
        const status = params.get(this.getAttribute("status-param") || "status");
        if (statusCodes.includes(status)) {
            this.status = status;
        }
        this.page = positiveInteger(params.get(this.getAttribute("page-param") || "page"), 1);
    }

    writeUrlState() {
        if (
            this.getAttribute("sync-url") === "false" ||
            typeof location === "undefined" ||
            typeof history === "undefined"
        ) {
            return;
        }
        const url = new URL(location.href);
        const statusParam = this.getAttribute("status-param") || "status";
        const pageParam = this.getAttribute("page-param") || "page";
        if (this.status === "all") {
            url.searchParams.delete(statusParam);
        } else {
            url.searchParams.set(statusParam, this.status);
        }
        if (this.page <= 1) {
            url.searchParams.delete(pageParam);
        } else {
            url.searchParams.set(pageParam, String(this.page));
        }
        history.replaceState(history.state, "", `${url.pathname}${url.search}${url.hash}`);
    }

    onFilterChange = (event) => {
        if (!event.target?.matches?.("[data-status-filter]")) {
            return;
        }
        const status = String(event.target.value || "all");
        if (!statusCodes.includes(status)) {
            return;
        }
        this.status = status;
        this.page = 1;
        this.writeUrlState();
        this.sync();
    };

    onPageChange = (event) => {
        if (!event.target?.matches?.("[data-pagination]")) {
            return;
        }
        this.page = positiveInteger(event.detail?.page, 1);
        this.writeUrlState();
        this.sync();
        this.scrollIntoView({ behavior: "smooth", block: "start" });
    };
}

customElements.define("BE5_TAG_TO_BE_REPLACED", CommerceAccountOffers);

// Controller dependencies stay below the artifact root so installation can bundle them.
export const statusCodes = [
    "all",
    "draft",
    "action_required",
    "under_review",
    "online",
    "paused",
    "rejected",
    "archived",
];

export const statusDefaults = {
    all: "Toutes",
    draft: "Brouillons",
    action_required: "Action requise",
    under_review: "En validation",
    online: "En ligne",
    paused: "En pause",
    rejected: "Refusées",
    archived: "Archivées",
};

export function positiveInteger(value, fallback) {
    const parsed = Number(value);
    return Number.isSafeInteger(parsed) && parsed > 0 ? parsed : fallback;
}

export function positiveIdentifier(value) {
    const identifier = String(value ?? "").trim();
    return /^[1-9]\d*$/.test(identifier) ? identifier : "";
}

export function setAttributeIfChanged(element, name, value) {
    if (element && element.getAttribute(name) !== value) {
        element.setAttribute(name, value);
    }
}

export function setTextIfChanged(element, value) {
    if (element && element.textContent !== value) {
        element.textContent = value;
    }
}

export function copyOptionalAttribute(source, target, name, targetName = name) {
    if (!target) {
        return;
    }
    const value = source.getAttribute(name)?.trim();
    if (value) {
        target.setAttribute(targetName, value);
    } else {
        target.removeAttribute(targetName);
    }
}

export function copyColorAttributes(source, target, prefix) {
    if (!target) {
        return;
    }
    for (const name of ["text-color", "background-color", "border-color", "accent-color"]) {
        copyOptionalAttribute(source, target, `${prefix}-${name}`, name);
    }
}

export function formatMoney(amount, currency, locale) {
    if (amount === null || amount === undefined || String(amount).trim() === "") {
        return "Prix à définir";
    }
    const value = Number(amount);
    if (!Number.isSafeInteger(value)) {
        return "Prix à définir";
    }
    try {
        return new Intl.NumberFormat(locale, {
            style: "currency",
            currency: String(currency || "EUR").toUpperCase(),
        }).format(value / 100);
    } catch {
        return `${(value / 100).toFixed(2)} ${String(currency || "EUR").toUpperCase()}`;
    }
}

export function formatDate(value, locale) {
    const date = new Date(String(value || ""));
    if (Number.isNaN(date.getTime())) {
        return "";
    }
    return `Modifiée le ${new Intl.DateTimeFormat(locale, { dateStyle: "medium" }).format(date)}`;
}

export function offerUrl(base, id, slug = "") {
    const hasPlaceholder = base.includes("{id}") || base.includes("{slug}");
    if (hasPlaceholder) {
        return base
            .replaceAll("{id}", encodeURIComponent(id || ""))
            .replaceAll("{slug}", encodeURIComponent(slug || ""));
    }
    const url = new URL(base, "https://cms.invalid");
    if (id) {
        url.searchParams.set("id", id);
    }
    return `${url.pathname}${url.search}${url.hash}`;
}

