export function isRangeValue(value, minimum, maximum, step) {
    if (!Number.isFinite(value) || value < minimum || value > maximum) {
        return false;
    }
    if (value === minimum || value === maximum) {
        return true;
    }
    const snapped = snapRangeValue(value, minimum, maximum, step, Number.NaN);
    const tolerance = Number.EPSILON * Math.max(1, Math.abs(value), Math.abs(snapped));
    return Number.isFinite(snapped) && Math.abs(value - snapped) <= tolerance;
}

export function snapRangeValue(value, minimum, maximum, step, fallback) {
    if (!Number.isFinite(value)) {
        return fallback;
    }
    const clamped = Math.min(maximum, Math.max(minimum, value));
    const snapped = minimum + Math.round((clamped - minimum) / step) * step;
    const bounded = Math.min(maximum, Math.max(minimum, snapped));
    const precision = rangePrecision(minimum, maximum, step);
    const normalized = precision <= 12 ? Number(bounded.toFixed(precision)) : Number(bounded.toPrecision(17));
    return Math.min(maximum, Math.max(minimum, normalized));
}

export function formatRangeValue(value, locale, precision) {
    if (precision > 12) {
        return String(value);
    }
    const options = { maximumFractionDigits: precision, useGrouping: false };
    try {
        return new Intl.NumberFormat(locale, options).format(value);
    } catch {
        return new Intl.NumberFormat(undefined, options).format(value);
    }
}

export function rangePrecision(...values) {
    return Math.min(20, Math.max(0, ...values.map(decimalPlaces)));
}

function decimalPlaces(value) {
    const [coefficient, exponentText] = Math.abs(value).toString().toLowerCase().split("e");
    const decimals = coefficient.split(".")[1]?.length ?? 0;
    return Math.max(0, decimals - Number(exponentText || 0));
}

import { formatRangeValue, rangePrecision } from "./range-values";

export function applyRangeView(elements, minimum, maximum, reflectManual, activeBound) {
    elements.minimumSlider.max = String(maximum);
    elements.maximumSlider.min = String(minimum);
    elements.minimumSlider.value = String(minimum);
    elements.maximumSlider.value = String(maximum);
    if (reflectManual) {
        elements.minimumControl.value = minimum === elements.domainMinimum ? "" : String(minimum);
        elements.maximumControl.value = maximum === elements.domainMaximum ? "" : String(maximum);
    }
    const span = elements.domainMaximum - elements.domainMinimum;
    const start = span > 0 ? ((minimum - elements.domainMinimum) / span) * 100 : 0;
    const end = span > 0 ? ((maximum - elements.domainMinimum) / span) * 100 : 100;
    elements.track?.style.setProperty("--range-start", `${start}%`);
    elements.track?.style.setProperty("--range-end", `${end}%`);
    const precision = rangePrecision(elements.domainMinimum, elements.domainMaximum, elements.step);
    const separator = minimum === maximum ? "" : ` – ${formatRangeValue(maximum, elements.locale, precision)}`;
    elements.output.textContent = `${formatRangeValue(minimum, elements.locale, precision)}${separator}${elements.unit ? ` ${elements.unit}` : ""}`;
    applyHandleLayers(elements, minimum, maximum, activeBound);
}

export function markRangePending(host) {
    host.setAttribute("data-range-status", "pending");
}

export function markRangeReady(host) {
    host.setAttribute("data-range-status", "ready");
    host.dispatchEvent(
        new CustomEvent("commerce-offer-filter:state", {
            bubbles: true,
            composed: true,
            detail: { state: "range-ready" },
        }),
    );
}

function applyHandleLayers(elements, minimum, maximum, activeBound) {
    let top = activeBound;
    if (minimum === maximum && !top) {
        top = minimum === elements.domainMaximum ? "minimum" : "maximum";
    }
    elements.minimumSlider.style.zIndex = top === "minimum" ? "2" : "1";
    elements.maximumSlider.style.zIndex = top === "maximum" ? "2" : "1";
}

import { element, filterWrapper } from "../schema/render-elements";

export function renderNumberRange(filterTag, field, controls, range) {
    const group = element(filterTag, {
        "data-numeric-range": "",
        "data-range-minimum": String(range.minimum),
        "data-range-maximum": String(range.maximum),
        "data-range-unit": field.unit || "",
    });
    const fieldset = element("fieldset", { "data-range-fieldset": "" });
    const legend = element("legend", { "data-range-legend": "" });
    legend.textContent = field.label;
    const heading = element("div", { "data-range-heading": "" });
    const label = element("span", { "data-range-label": "", "aria-hidden": "true" });
    label.textContent = field.label;
    const output = element("output", { "data-range-output": "", "aria-live": "polite" });
    heading.append(label, output);
    const track = element("div", { "data-range-track": "" });
    track.append(
        element("span", { "data-range-rail": "", "aria-hidden": "true" }),
        element("span", { "data-range-fill": "", "aria-hidden": "true" }),
        rangeInput(field, "minimum", range),
        rangeInput(field, "maximum", range),
    );
    const manual = element("div", { "data-range-manual": "" });
    manual.append(
        manualBound(
            filterTag,
            field,
            controls.find(({ operator }) => operator === "gte"),
            "minimum",
            range,
        ),
        manualBound(
            filterTag,
            field,
            controls.find(({ operator }) => operator === "lte"),
            "maximum",
            range,
        ),
    );
    fieldset.append(legend, heading, track, manual);
    group.append(fieldset);
    return group;
}

function rangeInput(field, bound, range) {
    return element("input", {
        type: "range",
        min: String(range.minimum),
        max: String(range.maximum),
        step: String(range.step),
        value: String(bound === "minimum" ? range.minimum : range.maximum),
        "data-range-slider": bound,
        "aria-label": `${field.label} — ${bound === "minimum" ? "minimum" : "maximum"}${field.unit ? ` (${field.unit})` : ""}`,
        ...(range.minimum === range.maximum ? { disabled: "" } : {}),
    });
}

function manualBound(filterTag, field, definition, bound, range) {
    const wrapper = filterWrapper(filterTag, field, definition);
    const proxy = element("input", {
        name: definition.param,
        type: "hidden",
        "cms-param-sync": definition.param,
        "data-filter-param": definition.param,
        "data-range-proxy": bound,
    });
    const label = element("label", { "data-range-bound": bound });
    const copy = document.createElement("span");
    copy.textContent = bound === "minimum" ? "Min." : "Max.";
    const endpoint = bound === "minimum" ? range.minimum : range.maximum;
    const control = element("input", {
        type: "number",
        min: String(range.minimum),
        max: String(range.maximum),
        step: String(range.step),
        placeholder: String(endpoint),
        inputmode: "decimal",
        "data-range-control": bound,
        "aria-label": `${field.label} — ${bound === "minimum" ? "minimum" : "maximum"}${field.unit ? ` (${field.unit})` : ""}`,
    });
    label.append(copy, control);
    wrapper.append(proxy, label);
    return wrapper;
}

export function basicSelect(label, attributes) {
    const template = document.createElement("template");
    template.innerHTML = "<basic-select></basic-select>";
    const select = template.content.firstElementChild;
    select.setAttribute("label", label);
    select.setAttribute("text-color", "var(--text-main)");
    select.setAttribute("background-color", "var(--bg-surface)");
    select.setAttribute("border-color", "var(--border-default)");
    select.setAttribute("accent-color", "var(--secondary-base)");
    for (const [name, value] of Object.entries(attributes)) {
        select.setAttribute(name, value);
    }
    return select;
}

export function basicOption(value, label) {
    const template = document.createElement("template");
    template.innerHTML = "<basic-option></basic-option>";
    const item = template.content.firstElementChild;
    item.setAttribute("value", value);
    item.textContent = label;
    return item;
}

export function filterWrapper(filterTag, field, definition) {
    return element(filterTag, {
        field: field.key,
        operator: definition.operator,
        "value-type": definition.valueType,
        "data-filterable-field": field.key,
    });
}

export function element(tag, attributes) {
    const value = document.createElement(tag);
    for (const [name, content] of Object.entries(attributes)) {
        value.setAttribute(name, content);
    }
    return value;
}

import { filterControls, filterableFields, numericRange, schemaBrands } from "./schema-helpers";
import { basicOption, basicSelect, element, filterWrapper } from "./render-elements";
import { renderNumberRange } from "../range/render-range";
import { schemaFilterStyle } from "./schema-style";

export function renderSchema(host, schema) {
    host.setAttribute("data-schema-status", "initializing");
    const schemaCategory = schema?.category?.fullSlug;
    if (typeof schemaCategory === "string" && schemaCategory.trim()) {
        host.setAttribute("data-schema-category", schemaCategory.trim());
    } else {
        host.removeAttribute("data-schema-category");
    }
    const stack = element("div", { "data-schema-filters": "" });
    const style = document.createElement("style");
    style.textContent = schemaFilterStyle.replaceAll("commerce-offer-filter", host.localName);
    stack.append(style);
    if (host.getAttribute("show-brand") !== "false") {
        stack.append(renderBrand(host, schema));
    }
    const fields = filterableFields(schema);
    if (fields.length > 0) {
        const heading = document.createElement("strong");
        heading.textContent = host.getAttribute("advanced-label") || "Filtres avancés";
        stack.append(heading);
    }
    for (const field of fields) {
        const controls = filterControls(field);
        const range = numericRange(field);
        if (
            range &&
            controls.some(({ operator }) => operator === "gte") &&
            controls.some(({ operator }) => operator === "lte")
        ) {
            stack.append(renderNumberRange(host.localName, field, controls, range));
            continue;
        }
        for (const control of controls) {
            stack.append(renderField(host.localName, field, control));
        }
    }
    if (stack.childElementCount === 1) {
        const empty = document.createElement("p");
        empty.textContent = host.getAttribute("empty-label") || "Aucun filtre supplémentaire pour cette catégorie.";
        stack.append(empty);
    }
    replaceSchemaContent(host, stack);
    setTimeout(() => {
        if (host.isConnected && host.contains(stack)) {
            publishSchemaState(host, "ready");
        }
    }, 0);
}

export function renderSchemaState(host, state, message = "") {
    const status = document.createElement("p");
    status.dataset.schemaState = state;
    status.setAttribute("role", state === "error" ? "alert" : "status");
    status.textContent =
        message ||
        (state === "loading"
            ? host.getAttribute("loading-label") || "Chargement des filtres…"
            : host.getAttribute("select-category-label") || "Choisis une catégorie pour afficher ses filtres.");
    replaceSchemaContent(host, status);
    publishSchemaState(host, state);
}

function replaceSchemaContent(host, content) {
    const authored = [...host.children].find(
        (child) => child.localName === "template" && child.hasAttribute("data-authored-filter-content"),
    );
    host.replaceChildren(...(authored ? [authored] : []), content);
}

function publishSchemaState(host, state) {
    host.setAttribute("data-schema-status", state);
    host.dispatchEvent(
        new CustomEvent("commerce-offer-filter:state", {
            bubbles: true,
            composed: true,
            detail: { state },
        }),
    );
}

function renderBrand(host, schema) {
    const select = basicSelect(host.getAttribute("brand-label") || "Marque", {
        name: "brand",
        "cms-param-sync": "brand",
        "data-commerce-param": "brand",
        "data-url-param": "brand",
        "data-filter-param": "brand",
    });
    select.append(
        basicOption("", host.getAttribute("brand-all-label") || "Toutes les marques"),
        ...schemaBrands(schema).map((brand) => basicOption(brand.slug, brand.name)),
    );
    return select;
}

function renderField(filterTag, field, definition) {
    const wrapper = filterWrapper(filterTag, field, definition);
    const options = Array.isArray(field.options) ? field.options : [];
    if (options.length > 0 || field.type === "boolean") {
        const select = basicSelect(field.label, {
            name: definition.param,
            "cms-param-sync": definition.param,
            "data-filter-param": definition.param,
        });
        select.append(basicOption("", `Tous · ${field.label}`));
        select.append(
            ...(field.type === "boolean"
                ? [basicOption("true", "Oui"), basicOption("false", "Non")]
                : options.map((value) => basicOption(String(value), String(value)))),
        );
        wrapper.append(select);
        return wrapper;
    }
    const label = element("label", { "data-schema-field": "" });
    const copy = document.createElement("span");
    copy.textContent = fieldLabel(field, definition.operator);
    const control = element("input", {
        name: definition.param,
        type: field.type === "number" ? "number" : "text",
        "cms-param-sync": definition.param,
        "data-filter-param": definition.param,
        ...(field.type === "number" ? { step: "any", inputmode: "decimal" } : {}),
    });
    label.append(copy, control);
    wrapper.append(label);
    return wrapper;
}

function fieldLabel(field, operator) {
    const unit = typeof field.unit === "string" && field.unit.trim() ? ` (${field.unit.trim()})` : "";
    const bound = operator === "gte" ? " — minimum" : operator === "lte" ? " — maximum" : "";
    return `${field.label}${bound}${unit}`;
}

export function filterableFields(schema) {
    if (!schema || typeof schema !== "object" || !Array.isArray(schema.fields)) {
        return [];
    }
    return schema.fields
        .filter(
            (field) =>
                field &&
                typeof field === "object" &&
                field.filterable === true &&
                typeof field.key === "string" &&
                isMetadataKey(field.key.trim()) &&
                typeof field.label === "string" &&
                Array.isArray(field.operators),
        )
        .sort((left, right) => numeric(left.position) - numeric(right.position) || left.key.localeCompare(right.key));
}

export function filterControls(field) {
    const operators = new Set(field.operators);
    if (field.type === "number") {
        const controls = [];
        if (operators.has("gte")) {
            controls.push({ operator: "gte", param: filterParam(field.key, "gte"), valueType: "number" });
        }
        if (operators.has("lte")) {
            controls.push({ operator: "lte", param: filterParam(field.key, "lte"), valueType: "number" });
        }
        if (controls.length === 0 && operators.has("eq")) {
            controls.push({ operator: "eq", param: filterParam(field.key, "eq"), valueType: "number" });
        }
        return controls;
    }
    if (operators.has("eq")) {
        return [
            {
                operator: "eq",
                param: filterParam(field.key, "eq"),
                valueType: field.type === "boolean" ? "boolean" : "string",
            },
        ];
    }
    return [];
}

export function numericRange(field) {
    const minimum = Number(field?.range?.minimum);
    const maximum = Number(field?.range?.maximum);
    const step = Number(field?.range?.step);
    if (
        field?.type !== "number" ||
        !Number.isFinite(minimum) ||
        !Number.isFinite(maximum) ||
        !Number.isFinite(step) ||
        minimum > maximum ||
        step <= 0
    ) {
        return null;
    }
    return { minimum, maximum, step };
}

export function filterParam(key, operator) {
    const safeKey = String(key).trim();
    const suffix = operator === "gte" ? ":gte" : operator === "lte" ? ":lte" : "";
    return `filter_${safeKey}${suffix}`;
}

export function legacyFilterParam(key, operator) {
    const safeKey = String(key).trim();
    const suffix = operator === "gte" ? "_min" : operator === "lte" ? "_max" : "";
    return `filter_${safeKey}${suffix}`;
}

export function schemaBrands(schema) {
    if (!schema || typeof schema !== "object" || !Array.isArray(schema.brands)) {
        return [];
    }
    return schema.brands.filter(
        (brand) =>
            brand &&
            typeof brand === "object" &&
            typeof brand.slug === "string" &&
            brand.slug.trim() &&
            typeof brand.name === "string" &&
            brand.name.trim(),
    );
}

function numeric(value) {
    const parsed = Number(value);
    return Number.isFinite(parsed) ? parsed : Number.MAX_SAFE_INTEGER;
}

function isMetadataKey(value) {
    return /^[A-Za-z][A-Za-z0-9_-]{0,63}$/.test(value);
}

const schemaRequests = new Map<string, Promise<unknown>>();

export async function loadSchema(url) {
    const key = url.href;
    const existing = schemaRequests.get(key);
    if (existing) {
        return existing;
    }
    const request = fetch(url, {
        credentials: "include",
        headers: { accept: "application/json" },
    })
        .then(async (response) => {
            const body = await response.json().catch(() => null);
            if (!response.ok) {
                throw new Error(
                    response.status === 404 ? "Catégorie indisponible." : "Impossible de charger les filtres.",
                );
            }
            if (!body || typeof body !== "object" || Array.isArray(body)) {
                throw new Error("Réponse de filtres invalide.");
            }
            return body;
        })
        .finally(() => schemaRequests.delete(key));
    schemaRequests.set(key, request);
    return request;
}

export function schemaSourceUrl(host) {
    const prefix = (host.getAttribute("source-prefix") || "/.cms/sources").replace(/\/+$/, "");
    const sourceId = encodeURIComponent(host.getAttribute("source-id") || "commerce");
    const endpoint = encodeURIComponent(host.getAttribute("schema-endpoint") || "offerFilterSchema");
    return `${prefix}/${sourceId}/${endpoint}`;
}

import { filterControls, filterableFields, legacyFilterParam, numericRange } from "./schema-helpers";
import { snapRangeValue } from "../range/range-values";

export function prepareSchemaFilterParams(host, schema) {
    if (typeof location === "undefined" || typeof history === "undefined") {
        return;
    }
    const params = new URLSearchParams(location.search);
    const migrated = migrateLegacyFilterParams(params, schema);
    const canonicalized = canonicalizeNumericFilterParams(params, schema);
    const changed = migrated || canonicalized;
    if (!changed) {
        return;
    }
    const query = params.toString();
    history.replaceState(history.state, "", `${location.pathname}${query ? `?${query}` : ""}${location.hash}`);
    queueMicrotask(() => host.ownerDocument.dispatchEvent(new Event("cms-params:change")));
}

function migrateLegacyFilterParams(params, schema) {
    const candidates = new Map();
    for (const field of filterableFields(schema)) {
        for (const control of filterControls(field)) {
            const legacy = legacyFilterParam(field.key, control.operator);
            const targets = candidates.get(legacy) || new Set();
            targets.add(control.param);
            candidates.set(legacy, targets);
        }
    }
    let changed = false;
    for (const [legacy, targets] of candidates) {
        if (!params.has(legacy) || targets.size !== 1) {
            continue;
        }
        const [current] = targets;
        if (current === legacy) {
            continue;
        }
        if (!params.has(current)) {
            params.set(current, params.get(legacy) || "");
        }
        params.delete(legacy);
        changed = true;
    }
    return changed;
}

function canonicalizeNumericFilterParams(params, schema) {
    let changed = false;
    for (const field of filterableFields(schema)) {
        const range = numericRange(field);
        if (!range) {
            continue;
        }
        const controls = new Map(filterControls(field).map((control) => [control.operator, control.param]));
        const minimumParam = controls.get("gte");
        const maximumParam = controls.get("lte");
        if (!minimumParam || !maximumParam) {
            continue;
        }
        const maximum = readRangeValue(params, maximumParam, range, range.maximum);
        const minimum = Math.min(readRangeValue(params, minimumParam, range, range.minimum), maximum);
        changed = writeRangeValue(params, minimumParam, minimum, range.minimum) || changed;
        changed = writeRangeValue(params, maximumParam, maximum, range.maximum) || changed;
    }
    return changed;
}

function readRangeValue(params, name, range, fallback) {
    const raw = params.get(name);
    const value = raw === null || raw.trim() === "" ? Number.NaN : Number(raw);
    return snapRangeValue(value, range.minimum, range.maximum, range.step, fallback);
}

function writeRangeValue(params, name, value, boundary) {
    if (value === boundary) {
        const existed = params.has(name);
        params.delete(name);
        return existed;
    }
    const canonical = String(value);
    if (params.get(name) === canonical) {
        return false;
    }
    params.set(name, canonical);
    return true;
}

import { numericRangeStyle } from "../range/range-style";

export const schemaFilterStyle = `
    commerce-offer-filter[schema-driven] [data-schema-filters] {
        display: grid;
        gap: 1rem;
    }

    commerce-offer-filter[schema-driven] [data-schema-field] {
        display: grid;
        gap: .35rem;
        color: var(--text-main, inherit);
        font-size: .925rem;
        font-weight: 700;
    }

    commerce-offer-filter[schema-driven] [data-schema-field] input {
        box-sizing: border-box;
        width: 100%;
        min-height: 2.65rem;
        padding: .55rem .7rem;
        border: 1px solid var(--border-default, color-mix(in srgb, currentColor 22%, transparent));
        border-radius: var(--radius-control, .375rem);
        color: var(--text-main, inherit);
        background: var(--bg-surface, Canvas);
        font: inherit;
        font-weight: 400;
    }

    commerce-offer-filter[schema-driven] [data-schema-field] input:focus-visible {
        outline: 2px solid var(--secondary-base, currentColor);
        outline-offset: 2px;
    }
    ${numericRangeStyle}
`;

import { filterControls, filterableFields } from "./schema-helpers";
import { loadSchema, schemaSourceUrl } from "./schema-loader";
import { prepareSchemaFilterParams } from "./schema-params";
import { renderSchema, renderSchemaState } from "./render-schema";

export class SchemaOfferFilters {
    constructor(host) {
        this.host = host;
        this.category = "";
        this.schema = null;
        this.controller = null;
        this.scheduled = false;
        this.inFlight = null;
        this.connected = false;
        this.scheduleTimer = null;
    }

    connect() {
        if (this.connected) {
            this.schedule();
            return;
        }
        this.connected = true;
        if (!this.schema) {
            this.host.setAttribute("data-schema-status", "pending");
        }
        this.host.ownerDocument.addEventListener("cms-params:change", this.schedule);
        this.host.ownerDocument.defaultView?.addEventListener("popstate", this.schedule);
        this.schedule();
    }

    disconnect() {
        if (!this.connected) {
            return;
        }
        this.connected = false;
        this.host.ownerDocument.removeEventListener("cms-params:change", this.schedule);
        this.host.ownerDocument.defaultView?.removeEventListener("popstate", this.schedule);
        this.controller?.abort();
        this.controller = null;
        this.inFlight = null;
        this.scheduled = false;
        if (this.scheduleTimer) {
            clearTimeout(this.scheduleTimer);
            this.scheduleTimer = null;
        }
    }

    invalidate() {
        this.controller?.abort();
        this.inFlight = null;
        this.category = "";
        this.schema = null;
        this.host.setAttribute("data-schema-status", "pending");
        this.schedule();
    }

    render() {
        if (this.schema) {
            renderSchema(this.host, this.schema);
        }
    }

    renderCurrent() {
        if (this.schema && this.category === this.currentCategory()) {
            this.render();
        }
    }

    schedule = () => {
        if (this.scheduled) {
            return;
        }
        this.scheduled = true;
        this.scheduleTimer = setTimeout(() => {
            this.scheduled = false;
            this.scheduleTimer = null;
            if (this.host.isConnected) {
                void this.sync();
            }
        }, 0);
    };

    async sync() {
        const category = this.currentCategory();
        if (!category) {
            if (this.category) {
                this.clearManagedParams();
            }
            this.controller?.abort();
            this.category = "";
            this.schema = null;
            this.host.removeAttribute("data-schema-category");
            renderSchemaState(this.host, "idle");
            return;
        }
        if (category === this.category && this.schema) {
            return;
        }
        if (this.category && category !== this.category) {
            this.clearManagedParams();
        }
        this.category = category;
        if (this.inFlight?.category === category) {
            return this.inFlight.promise;
        }
        this.controller?.abort();
        const controller = new AbortController();
        this.controller = controller;
        renderSchemaState(this.host, "loading");
        const promise = this.load(category, controller);
        this.inFlight = { category, promise };
        try {
            await promise;
        } finally {
            if (this.inFlight?.promise === promise) {
                this.inFlight = null;
            }
        }
    }

    managedParams() {
        const fields = filterableFields(this.schema);
        return [
            ...(this.host.getAttribute("show-brand") === "false" ? [] : ["brand"]),
            ...fields.flatMap((field) => filterControls(field).map((control) => control.param)),
        ];
    }

    async load(category, controller) {
        try {
            const url = new URL(schemaSourceUrl(this.host), this.host.ownerDocument.baseURI);
            url.searchParams.set("category", category);
            const body = await loadSchema(url);
            if (controller.signal.aborted || !this.host.isConnected || category !== this.category) {
                return;
            }
            prepareSchemaFilterParams(this.host, body);
            this.schema = body;
            renderSchema(this.host, body);
        } catch (error) {
            if (controller.signal.aborted) {
                return;
            }
            console.error(error);
            this.schema = null;
            renderSchemaState(this.host, "error", "Impossible de charger les filtres de cette catégorie.");
        }
    }

    clearManagedParams() {
        if (typeof location === "undefined" || typeof history === "undefined") {
            return;
        }
        const params = new URLSearchParams(location.search);
        let changed = false;
        for (const name of this.managedParams()) {
            if (params.has(name)) {
                params.delete(name);
                changed = true;
            }
        }
        if (!changed) {
            return;
        }
        const query = params.toString();
        history.replaceState(history.state, "", `${location.pathname}${query ? `?${query}` : ""}${location.hash}`);
        queueMicrotask(() => this.host.ownerDocument.dispatchEvent(new Event("cms-params:change")));
    }

    currentCategory() {
        if (typeof location === "undefined") {
            return "";
        }
        return (
            new URLSearchParams(location.search).get(this.host.getAttribute("category-param") || "category")?.trim() ||
            ""
        );
    }
}

