export function salePresentationStatus(order) {
    const orderStatus = String(order?.status || "unknown");
    if (orderStatus !== "active") {
        return orderStatus;
    }
    const fulfillmentStatus = String(order?.fulfillment?.status || order?.fulfillmentStatus || "");
    return Object.hasOwn(saleStatusDefaults, fulfillmentStatus) && fulfillmentStatus !== "active"
        ? fulfillmentStatus
        : orderStatus;
}

export function formatMoney(amount, currency, locale = "fr-FR", signDisplay = "auto") {
    const value = Number(amount);
    if (!Number.isSafeInteger(value)) {
        return "—";
    }
    try {
        return new Intl.NumberFormat(locale, {
            style: "currency",
            currency: String(currency || "EUR").toUpperCase(),
            signDisplay,
        }).format(value / 100);
    } catch {
        const sign = signDisplay === "always" && value >= 0 ? "+" : "";
        return `${sign}${(value / 100).toFixed(2)} ${String(currency || "EUR").toUpperCase()}`;
    }
}

export function formatDate(value, locale = "fr-FR") {
    const date = new Date(String(value || ""));
    if (Number.isNaN(date.getTime())) {
        return "Date indisponible";
    }
    return new Intl.DateTimeFormat(locale, { dateStyle: "long" }).format(date);
}

export function variantLabel(snapshot) {
    const options = Array.isArray(snapshot?.options) ? snapshot.options : [];
    if (options.length) {
        return options
            .map((option) => {
                const axis = option.axisLabel || option.axisKey;
                const value = option.valueLabel || option.valueKey;
                return [axis, value].filter(Boolean).join(" : ");
            })
            .filter(Boolean)
            .join(" · ");
    }
    return String(snapshot?.title || "");
}

export function conditionLabel(code) {
    const labels = {
        new: "Neuf",
        like_new: "Comme neuf",
        very_good: "Très bon état",
        good: "Bon état",
        fair: "État correct",
        poor: "État usé",
    };
    return labels[String(code || "")] || String(code || "").replaceAll("_", " ");
}

export function shippingAmount(order) {
    const snapshot = order?.financialTerms?.shippingAmount;
    if (Number.isSafeInteger(snapshot) && snapshot >= 0) {
        return snapshot;
    }
    const explicit = Number(order?.shippingAmount);
    if (Number.isSafeInteger(explicit) && explicit >= 0) {
        return explicit;
    }
    return NaN;
}

export function sellerProceedsAmount(order) {
    return financialAmount(order, "sellerProceedsAmount");
}

export function sellerMerchandiseAmount(order) {
    const amount = financialAmount(order, "merchandiseSubtotalAmount");
    if (Number.isSafeInteger(amount)) {
        return amount;
    }
    const fallback = Number(order?.subtotalAmount);
    return Number.isSafeInteger(fallback) && fallback >= 0 ? fallback : NaN;
}

export function sellerCommissionAmount(order) {
    return financialAmount(order, "sellerCommissionAmount");
}

export function platformShippingShareAmount(order) {
    return financialAmount(order, "platformShippingShareAmount");
}

export function sellerShippingShareAmount(order) {
    return financialAmount(order, "sellerShippingShareAmount");
}

function financialAmount(order, field) {
    const value = order?.financialTerms?.[field];
    return Number.isSafeInteger(value) && value >= 0 ? value : NaN;
}

export function errorMessage(error, fallback) {
    const message = error instanceof Error ? error.message : String(error || "");
    return /cms|api key/i.test(message) ? fallback : message || fallback;
}

{
    "default-tag": "commerce-sale-detail",
    "bloc": "./Bloc.ts",
    "editor": "./BlocEditor.ts",
    "defaultContent": "./default.html",
    "meta": {
        "title": "Sale detail",
        "description": "Authenticated seller order detail with immutable line and financial snapshots, net proceeds, status, and a fulfillment composition slot."
    }
}

import {
    conditionLabel,
    formatDate,
    formatMoney,
    platformShippingShareAmount,
    salePresentationStatus,
    sellerCommissionAmount,
    sellerMerchandiseAmount,
    sellerProceedsAmount,
    sellerShippingShareAmount,
    shippingAmount,
    variantLabel,
} from "./helpers";

export function renderSale(host, order) {
    host.setText("[data-order-number]", order.orderNumber || order.publicId || `Vente ${order.id}`);
    host.setText(
        "[data-order-date]",
        `${host.text("date-prefix", "Vendue le")} ${formatDate(order.createdAt, host.locale)}`,
    );
    const status = host.root.querySelector("[data-order-status]");
    const presentationStatus = salePresentationStatus(order);
    status.dataset.status = presentationStatus;
    status.textContent = host.statusLabel(presentationStatus);
    const lines = Array.isArray(order.lines) ? order.lines : [];
    host.root
        .querySelector("[data-lines]")
        .replaceChildren(...lines.map((line) => renderLine(host, line, order.currency)));
    const currency = order.financialTerms?.currency || order.currency;
    host.setText("[data-subtotal]", formatMoney(sellerMerchandiseAmount(order), currency, host.locale));
    const commission = sellerCommissionAmount(order);
    host.setText("[data-commission]", formatMoney(commission === 0 ? 0 : -commission, currency, host.locale));
    host.setText("[data-shipping]", sellerShippingValue(host, order, currency));
    host.setText("[data-total]", formatMoney(sellerProceedsAmount(order), currency, host.locale));
}

function sellerShippingValue(host, order, currency) {
    const total = shippingAmount(order);
    const sellerShare = sellerShippingShareAmount(order);
    const platformShare = platformShippingShareAmount(order);
    if (![total, sellerShare, platformShare].every(Number.isSafeInteger)) {
        return "—";
    }
    if (sellerShare + platformShare !== total) {
        return "—";
    }
    if (sellerShare > 0) {
        return formatMoney(sellerShare, currency, host.locale, "always");
    }
    if (total === 0) {
        return formatMoney(0, currency, host.locale);
    }
    if (platformShare === total) {
        return host.text("platform-shipping-label", "Prise en charge par Courtside");
    }
    return "—";
}

function renderLine(host, line, currency) {
    const row = document.createElement("article");
    row.className = "sale-line";
    const copy = document.createElement("div");
    copy.className = "line-copy";
    const title = document.createElement("strong");
    title.textContent = line.title || line.offerSnapshot?.title || host.text("fallback-article-label", "Article");
    const details = [
        variantLabel(line.variantSnapshot),
        line.quantity > 1 ? `${host.text("quantity-label", "Quantité")} : ${line.quantity}` : "",
        line.offerSnapshot?.conditionCode ? conditionLabel(line.offerSnapshot.conditionCode) : "",
    ].filter(Boolean);
    const meta = document.createElement("span");
    meta.className = "line-meta";
    meta.textContent = details.join(" · ");
    meta.hidden = !details.length;
    const price = document.createElement("strong");
    price.className = "line-price";
    price.textContent = formatMoney(line.totalAmount, currency, host.locale);
    copy.append(title, meta);
    row.append(copy, price);
    return row;
}

export function copyColors(host, target, prefix) {
    for (const name of ["text-color", "background-color", "border-color", "accent-color"]) {
        const value = host.getAttribute(`${prefix}-${name}`)?.trim();
        if (value) {
            target.setAttribute(name, value);
        } else {
            target.removeAttribute(name);
        }
    }
}

