blocs/domains/forms/form-renderer/render.content:
:where(forms-renderer) {
    --forms-accent: var(--integration-ulvia-forms-accent, var(--primary-base, #b9583f));
    --forms-paper: var(--integration-ulvia-forms-background, var(--bg-surface, #fffdf9));
    --forms-ink: var(--integration-ulvia-forms-text, var(--text-main, #292724));
    --forms-muted: var(--integration-ulvia-forms-muted-text, var(--text-muted, #77716b));
    --forms-line: var(--integration-ulvia-forms-border, var(--border-default, #dfd8ce));
    display: block;
    width: min(46rem, 100%);
    margin-inline: auto;
    color: var(--forms-ink);
    font-family: inherit;
}

:where(forms-renderer) form {
    display: grid;
    gap: 0;
    padding: clamp(1.25rem, 4vw, 3.5rem);
    border: 1px solid var(--forms-line);
    border-radius: clamp(1rem, 2vw, 1.5rem);
    background: var(--forms-paper);
    box-shadow: 0 1.5rem 4rem color-mix(in srgb, var(--forms-ink) 8%, transparent);
}

:where(forms-renderer) .forms-progress-label {
    margin: 0 0 .6rem;
    color: var(--forms-accent);
    font-size: .75rem;
    font-weight: 700;
    letter-spacing: .12em;
    text-transform: uppercase;
}

:where(forms-renderer) progress {
    width: 100%;
    height: .25rem;
    margin: 0 0 clamp(2rem, 5vw, 3.5rem);
    overflow: hidden;
    border: 0;
    border-radius: 1rem;
    background: color-mix(in srgb, var(--forms-line) 75%, transparent);
    accent-color: var(--forms-accent);
}

:where(forms-renderer) progress::-webkit-progress-bar {
    background: color-mix(in srgb, var(--forms-line) 75%, transparent);
}

:where(forms-renderer) progress::-webkit-progress-value,
:where(forms-renderer) progress::-moz-progress-bar {
    background: var(--forms-accent);
}

:where(forms-renderer) h2 {
    margin: 0 0 .75rem;
    font-family: "Iowan Old Style", Baskerville, Georgia, serif;
    font-size: clamp(2rem, 5vw, 3.2rem);
    font-weight: 600;
    letter-spacing: -.035em;
    line-height: 1.08;
}

:where(forms-renderer) .forms-step-description {
    max-width: 38rem;
    margin: 0 0 2.25rem;
    color: var(--forms-muted);
    line-height: 1.65;
}

:where(forms-renderer) .forms-fields {
    display: grid;
    gap: 1.4rem;
}

:where(forms-renderer) .forms-trap {
    position: absolute;
    left: -10000px;
    width: 1px;
    height: 1px;
    opacity: 0;
    pointer-events: none;
}

:where(forms-renderer) .forms-actions {
    display: flex;
    justify-content: flex-end;
    gap: .75rem;
    margin-top: 2.75rem;
    padding-top: 1.5rem;
    border-top: 1px solid var(--forms-line);
}

:where(forms-renderer) .forms-actions basic-button:first-child:not(:last-child) {
    margin-right: auto;
}

:where(forms-renderer) .forms-status,
:where(forms-renderer) .forms-success {
    padding: clamp(2rem, 6vw, 4rem);
    border: 1px solid var(--forms-line);
    border-radius: 1.5rem;
    background: var(--forms-paper);
    text-align: center;
}

:where(forms-renderer) .forms-status.is-error {
    border-color: color-mix(in srgb, #b42318 40%, var(--forms-line));
    color: #b42318;
}

:where(forms-renderer) .forms-status button {
    min-height: 2.75rem;
    padding: .55rem 1rem;
    border: 1px solid currentColor;
    border-radius: .6rem;
    background: transparent;
    color: inherit;
    cursor: pointer;
}

:where(forms-renderer) .forms-success > span {
    display: grid;
    width: 3.5rem;
    height: 3.5rem;
    margin: 0 auto 1.5rem;
    place-items: center;
    border-radius: 50%;
    background: color-mix(in srgb, #5c7a50 16%, transparent);
    color: #4f7045;
    font-size: 1.4rem;
}

@media (max-width: 36rem) {
    :where(forms-renderer) form {
        padding-inline: 1.1rem;
        border-right: 0;
        border-left: 0;
        border-radius: 0;
        box-shadow: none;
    }
}

:where(forms-renderer) .forms-image-choice {
    min-width: 0;
    margin: 0;
    padding: 0;
    border: 0;
}

:where(forms-renderer) .forms-image-choice legend {
    margin-bottom: .45rem;
    font-weight: 700;
}

:where(forms-renderer) .forms-image-choice-hint {
    margin: 0 0 .8rem;
    color: var(--forms-muted);
    font-size: .9rem;
}

:where(forms-renderer) .forms-image-choice-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(min(10rem, 100%), 1fr));
    gap: .8rem;
}

:where(forms-renderer) .forms-image-choice-option {
    position: relative;
    cursor: pointer;
}

:where(forms-renderer) .forms-image-choice-option > input {
    position: absolute;
    width: 1px;
    height: 1px;
    opacity: 0;
}

:where(forms-renderer) .forms-image-choice-card {
    display: grid;
    height: 100%;
    overflow: hidden;
    border: 1px solid var(--forms-line);
    border-radius: .85rem;
    background: color-mix(in srgb, var(--forms-paper) 92%, var(--forms-line));
    transition: border-color 140ms ease, box-shadow 140ms ease, transform 140ms ease;
}

:where(forms-renderer) .forms-image-choice-card img {
    width: 100%;
    aspect-ratio: 4 / 3;
    object-fit: cover;
    background: var(--forms-line);
}

:where(forms-renderer) .forms-image-choice-card > span {
    padding: .8rem .9rem;
    font-weight: 700;
}

:where(forms-renderer) .forms-image-choice-option:hover .forms-image-choice-card {
    transform: translateY(-1px);
}

:where(forms-renderer) .forms-image-choice-option > input:checked + .forms-image-choice-card {
    border-color: var(--forms-accent);
    box-shadow: 0 0 0 2px color-mix(in srgb, var(--forms-accent) 24%, transparent);
}

:where(forms-renderer) .forms-image-choice-option > input:focus-visible + .forms-image-choice-card {
    outline: 3px solid color-mix(in srgb, var(--forms-accent) 35%, transparent);
    outline-offset: 2px;
}

import { optionKey, safeImageSource, type FormField } from "../definition";

export interface ImageChoiceItem {
    key: string;
    label: string;
    imageUrl: string;
    imageAlt: string;
    selected: boolean;
}

export type ImageSource = (mediaId: string) => string;

export function imageChoiceItems(
    field: FormField,
    saved: string | string[] | undefined,
    imageSource?: ImageSource,
): ImageChoiceItem[] {
    const selected = new Set(Array.isArray(saved) ? saved : saved ? [saved] : []);
    return (field.options ?? []).map((option) => ({
        key: optionKey(option),
        label: option.label,
        imageUrl: option.image ? (imageSource?.(String(option.image.mediaId)) ?? "") : safeImageSource(option.imageUrl),
        imageAlt: option.image?.alt ?? option.imageAlt ?? "",
        selected: selected.has(optionKey(option)),
    }));
}

export function imageChoiceControl(
    field: FormField,
    saved: string | string[] | undefined,
    imageSource?: ImageSource,
): HTMLElement {
    const fieldset = document.createElement("fieldset");
    fieldset.className = "forms-image-choice";
    const legend = document.createElement("legend");
    legend.textContent = field.label;
    fieldset.append(legend);
    if (field.hint) {
        const hint = document.createElement("p");
        hint.id = `forms-hint-${field.key}`;
        hint.className = "forms-image-choice-hint";
        hint.textContent = field.hint;
        fieldset.setAttribute("aria-describedby", hint.id);
        fieldset.append(hint);
    }

    const grid = document.createElement("div");
    grid.className = "forms-image-choice-grid";
    const inputs = imageChoiceItems(field, saved, imageSource).map((option) => {
        const label = document.createElement("label");
        label.className = "forms-image-choice-option";
        const input = document.createElement("input");
        input.type = field.multiple ? "checkbox" : "radio";
        input.name = field.key;
        input.value = option.key;
        input.checked = option.selected;
        input.required = Boolean(field.required && !field.multiple);

        const card = document.createElement("span");
        card.className = "forms-image-choice-card";
        const image = document.createElement("img");
        image.src = option.imageUrl;
        image.alt = option.imageAlt;
        image.loading = "lazy";
        const caption = document.createElement("span");
        caption.textContent = option.label;
        card.append(image, caption);
        label.append(input, card);
        grid.append(label);
        return input;
    });
    fieldset.append(grid);
    bindMultipleRequired(inputs, Boolean(field.required && field.multiple));
    return fieldset;
}

function bindMultipleRequired(inputs: HTMLInputElement[], required: boolean): void {
    if (!required || !inputs[0]) {
        return;
    }
    const update = (): void => {
        inputs[0]!.setCustomValidity(inputs.some((input) => input.checked) ? "" : "Choose at least one option.");
    };
    inputs.forEach((input) => input.addEventListener("change", update));
    update();
}

import { optionKey, type FormAnswers, type FormDefinition, type FormField } from "../definition";
import { imageChoiceControl, type ImageSource } from "./imageChoice";

export function formsRoot(host: HTMLElement): HTMLElement {
    let root = host.querySelector<HTMLElement>("[data-forms-root]");
    if (!root) {
        root = document.createElement("div");
        root.dataset.formsRoot = "";
        host.append(root);
    }
    return root;
}

export function sourceBase(host: HTMLElement): string {
    const prefix = (host.getAttribute("source-prefix") || "/.cms/sources").replace(/\/+$/, "");
    const sourceId = encodeURIComponent(host.getAttribute("source-id") || "forms");
    return `${prefix}/${sourceId}`;
}

function setOptional(element: HTMLElement, name: string, value: string | undefined): void {
    if (value) {
        element.setAttribute(name, value);
    }
}

function controlFor(field: FormField, saved: string | string[] | undefined, imageSource?: ImageSource): HTMLElement {
    if (field.type === "textarea") {
        return standardControl("basic-textarea", field, saved);
    }
    if (field.type === "select") {
        const select = standardControl("basic-select", field, saved);
        for (const option of field.options ?? []) {
            const item = document.createElement("basic-option");
            item.setAttribute("value", optionKey(option));
            item.textContent = option.label;
            select.append(item);
        }
        return select;
    }
    if (field.type === "choice") {
        if (field.presentation === "image-grid") {
            return imageChoiceControl(field, saved, imageSource);
        }
        const group = standardControl("basic-chip-group", field, saved);
        group.setAttribute("mode", field.multiple ? "multiple" : "single");
        const selected = new Set(Array.isArray(saved) ? saved : saved ? [saved] : []);
        for (const option of field.options ?? []) {
            const key = optionKey(option);
            const chip = document.createElement("basic-chip");
            chip.setAttribute("value", key);
            chip.toggleAttribute("selected", selected.has(key));
            chip.textContent = option.label;
            group.append(chip);
        }
        return group;
    }
    if (field.type === "checkbox") {
        const checkbox = document.createElement("basic-checkbox");
        checkbox.setAttribute("name", field.key);
        checkbox.setAttribute("value", "true");
        checkbox.setAttribute("unchecked-value", "false");
        checkbox.toggleAttribute("checked", saved === "true");
        checkbox.toggleAttribute("required", Boolean(field.required));
        checkbox.textContent = field.label;
        return checkbox;
    }
    return standardControl("basic-input", field, saved);
}

function standardControl(tag: string, field: FormField, saved: string | string[] | undefined): HTMLElement {
    const element = document.createElement(tag);
    element.setAttribute("name", field.key);
    element.setAttribute("label", field.label);
    if (field.type !== "select" && field.type !== "choice") {
        element.setAttribute("type", field.type);
    }
    setOptional(element, "hint", field.hint);
    setOptional(element, "placeholder", field.placeholder);
    setOptional(element, "autocomplete", field.autocomplete);
    if (saved !== undefined) {
        element.setAttribute("value", Array.isArray(saved) ? saved.join(",") : saved);
    }
    element.toggleAttribute("required", Boolean(field.required));
    return element;
}

export interface StepViewActions {
    back(): void;
    submit(form: HTMLFormElement): void;
}

export function renderStep(
    root: HTMLElement,
    definition: FormDefinition,
    stepIndex: number,
    values: FormAnswers,
    actions: StepViewActions,
    imageSource?: ImageSource,
): void {
    const step = definition.steps[stepIndex];
    const form = document.createElement("form");
    form.noValidate = false;
    form.addEventListener("submit", (event) => {
        event.preventDefault();
        actions.submit(form);
    });

    const progress = document.createElement("p");
    progress.className = "forms-progress-label";
    progress.textContent = `Step ${stepIndex + 1} of ${definition.steps.length}`;
    const meter = document.createElement("progress");
    meter.max = definition.steps.length;
    meter.value = stepIndex + 1;
    meter.setAttribute("aria-label", progress.textContent);
    const title = document.createElement("h2");
    title.textContent = step.title;
    form.append(progress, meter, title);
    if (step.description) {
        const description = document.createElement("p");
        description.className = "forms-step-description";
        description.textContent = step.description;
        form.append(description);
    }
    const fields = document.createElement("div");
    fields.className = "forms-fields";
    for (const field of step.fields) {
        fields.append(controlFor(field, values[field.key], imageSource));
    }
    const honeypot = document.createElement("input");
    honeypot.className = "forms-trap";
    honeypot.name = "website";
    honeypot.tabIndex = -1;
    honeypot.autocomplete = "off";
    fields.append(honeypot);
    form.append(fields, navigation(definition, stepIndex, actions));
    root.replaceChildren(form);
}

function navigation(definition: FormDefinition, stepIndex: number, actions: StepViewActions): HTMLElement {
    const footer = document.createElement("footer");
    footer.className = "forms-actions";
    if (stepIndex > 0) {
        const wrapper = document.createElement("basic-button");
        wrapper.setAttribute("appearance", "ghost");
        const button = document.createElement("button");
        button.type = "button";
        button.textContent = "Back";
        button.addEventListener("click", actions.back);
        wrapper.append(button);
        footer.append(wrapper);
    }
    const nextWrapper = document.createElement("basic-button");
    const next = document.createElement("button");
    next.type = "submit";
    next.textContent = stepIndex + 1 === definition.steps.length ? definition.submitLabel || "Submit" : "Continue";
    nextWrapper.append(next);
    footer.append(nextWrapper);
    return footer;
}

export function answersFrom(form: HTMLFormElement): FormAnswers {
    const answers: FormAnswers = {};
    for (const [key, value] of new FormData(form)) {
        if (key === "website" || typeof value !== "string") {
            continue;
        }
        const previous = answers[key];
        answers[key] =
            previous === undefined ? value : Array.isArray(previous) ? [...previous, value] : [previous, value];
    }
    return answers;
}

import baseCss from "./base.css" with { type: "text" };
import imageChoiceCss from "./imageChoice.css" with { type: "text" };

export function installRendererStyles(host: HTMLElement): void {
    if (host.querySelector("style[data-forms-renderer-styles]")) {
        return;
    }
    const style = document.createElement("style");
    style.dataset.formsRendererStyles = "";
    style.textContent = `${baseCss}\n${imageChoiceCss}`;
    host.prepend(style);
}

