        "accept",
        "accent-color",
        "background-color",
        "border-color",
        "capture",
        "disabled",
        "empty-label",
        "hint",
        "label",
        "multiple",
        "name",
        "picker-label",
        "preview-shape",
        "preview-size",
        "required",
        "text-color",
    ];

    constructor() {
        super();
        this.root = this.attachShadow({ mode: "open" });
        this.internals = this.attachInternals();
        this.showValidation = false;
        this.previewUrl = "";
        this.previewedFile = null;
        this.root.innerHTML = `
            <style>
