                .preview ::slotted(*) { display: block; width: 100%; height: 100%; object-fit: cover; }
                .selected-preview { background-position: center; background-size: cover; }
                :host([preview-shape="circle"]) .preview { border-radius: 50%; }
                :host([preview-size="small"]) { --cms-file-preview-size: 3.5rem; }
                :host([preview-size="large"]) { --cms-file-preview-size: 7rem; }
                .picker {
                    position: relative;
                    display: flex;
                    align-items: center;
                    gap: .75rem;
                    min-height: var(--cms-input-height, 2.75rem);
                    width: max-content;
                    max-width: 100%;
                    cursor: pointer;
                }
                .picker-button {
                    display: inline-flex;
                    align-items: center;
                    justify-content: center;
                    min-height: 2.5rem;
                    padding: .5rem .8rem;
                    border: 1px solid var(--cms-file-border-color, var(--_file-border));
                    border-radius: var(--cms-input-radius, var(--integration-ulvia-basic-blocs-action-radius, .5rem));
                    background: var(--cms-file-background, var(--_file-background));
                    color: var(--cms-file-color, var(--_file-color));
                    font-weight: 700;
                    white-space: nowrap;
                }
                .file-name {
                    overflow: hidden;
                    color: var(--integration-ulvia-basic-blocs-muted-text, var(--text-muted, color-mix(in srgb, currentColor 65%, transparent)));
                    text-overflow: ellipsis;
                    white-space: nowrap;
                }
                input {
                    position: absolute;
                    width: 1px;
                    height: 1px;
                    padding: 0;
