type ThemeColorRole = {
    token: string;
    fallbackToken?: string;
    system: string;
};

type BasicColorScheme = {
    value: string;
    label: string;
    roles: {
        base: ThemeColorRole;
        foreground: ThemeColorRole;
        muted: ThemeColorRole;
        contrasted: ThemeColorRole;
        border: ThemeColorRole;
        focus: ThemeColorRole;
    };
};

const role = (token: string, system: string, fallbackToken?: string): ThemeColorRole => ({
    token,
    ...(fallbackToken ? { fallbackToken } : {}),
    system,
});

export const BASIC_COLOR_SCHEMES: readonly BasicColorScheme[] = [
    {
        value: "primary",
        label: "Primary",
        roles: {
            base: role("action-background", "CanvasText", "primary-base"),
            foreground: role("action-text", "Canvas", "primary-foreground"),
            muted: role("action-muted-background", "Canvas", "primary-muted"),
            contrasted: role("action-muted-text", "CanvasText", "primary-contrasted"),
            border: role("action-border", "CanvasText", "primary-base"),
            focus: role("focus-color", "Highlight", "primary-base"),
        },
    },
    scheme("secondary", "Secondary"),
    {
        value: "neutral",
        label: "Neutral",
        roles: {
            base: role("surface-text", "CanvasText"),
            foreground: role("surface-background", "Canvas"),
            muted: role("subtle-background", "Canvas"),
            contrasted: role("surface-text", "CanvasText"),
            border: role("surface-border", "currentColor"),
            focus: role("surface-text", "Highlight"),
        },
    },
    scheme("info", "Information"),
    scheme("success", "Success"),
    scheme("warning", "Warning"),
    scheme("danger", "Danger"),
];

export const BASIC_COLOR_SCHEME_OPTIONS = BASIC_COLOR_SCHEMES.map(({ label, value }) => ({ label, value }));

export function basicColorSchemeCss(defaultTone = "primary"): string {
    return BASIC_COLOR_SCHEMES.map((colorScheme) => {
        const selectors = `${colorScheme.value === defaultTone ? ":host,\n" : ""}:host([tone="${colorScheme.value}"])`;
        const declarations = Object.entries(colorScheme.roles)
            .map(([name, value]) => `    --_tone-${name}: ${roleValue(value)};`)
            .join("\n");
        return `${selectors} {\n${declarations}\n}`;
    }).join("\n\n");
}

function scheme(value: string, label: string): BasicColorScheme {
    return {
        value,
        label,
        roles: {
            base: role(`${value}-base`, "CanvasText"),
            foreground: role(`${value}-foreground`, "Canvas"),
            muted: role(`${value}-muted`, "Canvas"),
            contrasted: role(`${value}-contrasted`, "CanvasText"),
            border: role(`${value}-base`, "currentColor"),
            focus: role(`${value}-base`, "Highlight"),
        },
    };
}

function roleValue(value: ThemeColorRole): string {
    const fallback = value.fallbackToken
        ? `var(--integration-ulvia-basic-blocs-${value.fallbackToken}, ${value.system})`
        : value.system;
    return `var(--integration-ulvia-basic-blocs-${value.token}, ${fallback})`;
}

import { trapMenuFocus } from "./focus";

let generatedId = 0;

export class BasicMenuController {
    constructor(host) {
        this.host = host;
        this.connected = false;
        this.lastState = undefined;
        this.previousOverflow = "";
        this.triggerElement = undefined;
        this.onClick = this.onClick.bind(this);
        this.onKeydown = this.onKeydown.bind(this);
        this.onSlotChange = this.onSlotChange.bind(this);
    }

    connect() {
        if (this.connected) {
            return;
        }
        this.connected = true;
        this.host.addEventListener("click", this.onClick);
        this.host.ownerDocument.addEventListener("keydown", this.onKeydown);
        this.host.shadowRoot?.addEventListener("slotchange", this.onSlotChange);
        this.sync();
    }

    disconnect() {
        this.connected = false;
        this.host.removeEventListener("click", this.onClick);
        this.host.ownerDocument.removeEventListener("keydown", this.onKeydown);
        this.host.shadowRoot?.removeEventListener("slotchange", this.onSlotChange);
        this.unlockScroll();
    }

    open() {
        if (this.trigger()) {
            this.host.setAttribute("open", "");
        }
    }

    close() {
        this.host.removeAttribute("open");
    }

    toggle() {
        if (this.host.hasAttribute("open")) {
            this.close();
        } else {
            this.open();
        }
    }

    sync() {
        const open = this.host.hasAttribute("open");
        const panel = this.panel();
        const trigger = this.trigger();
        const panelId = this.panelId();
        panel?.setAttribute("id", panelId);
        panel?.setAttribute("aria-hidden", String(!open));
        panel?.setAttribute("aria-label", this.host.getAttribute("navigation-label")?.trim() || "Menu navigation");
        const closeLabel = this.host.getAttribute("close-label")?.trim() || "Close";
        this.host.shadowRoot?.querySelector("[data-close-label]")?.replaceChildren(closeLabel);
        if (trigger) {
            trigger.setAttribute("aria-expanded", String(open));
            trigger.setAttribute("aria-haspopup", "dialog");
            this.linkAriaControl(trigger, panel);
        }
        if (open) {
            this.lockScroll();
            requestAnimationFrame(() => panel?.focus());
        } else {
            this.unlockScroll();
            if (this.lastState === true) {
                this.triggerElement?.focus();
            }
        }
        if (open !== this.lastState) {
            this.lastState = open;
            this.host.dispatchEvent(
                new CustomEvent("basic-menu-state", {
                    bubbles: true,
                    composed: true,
                    detail: { id: this.host.id, open },
                }),
            );
        }
    }

    onClick(event) {
        const path = event.composedPath();
        const trigger = this.trigger();
        if (trigger && path.includes(trigger)) {
            event.preventDefault();
            this.triggerElement = trigger;
            this.toggle();
            return;
        }
        const closes = path.some(
            (candidate) => candidate instanceof Element && candidate.hasAttribute("data-menu-close"),
        );
        const navigation = path.some(
            (candidate) => candidate instanceof HTMLAnchorElement && candidate.getAttribute("slot") === "navigation",
        );
        if (closes || (navigation && this.host.getAttribute("close-on-navigation") !== "off")) {
            this.close();
        }
    }

    onKeydown(event) {
        if (!this.host.hasAttribute("open")) {
            return;
        }
        if (event.key === "Escape") {
            event.preventDefault();
            this.close();
            return;
        }
        if (event.key !== "Tab") {
            return;
        }
        trapMenuFocus(this.host, event, this.trigger());
    }

    onSlotChange() {
        this.triggerElement = undefined;
        this.sync();
    }

    trigger() {
        const assigned = this.host.querySelector(':scope > [slot="trigger"]');
        if (assigned instanceof HTMLButtonElement) {
            return assigned;
        }
        if (assigned?.localName === "basic-button") {
            const button = assigned.querySelector(":scope > button");
            return button instanceof HTMLButtonElement ? button : undefined;
        }
        return undefined;
    }

    panel() {
        return this.host.shadowRoot?.querySelector('[part="panel"]');
    }

    panelId() {
        if (!this.host.id) {
            generatedId += 1;
            this.host.id = `basic-menu-${generatedId}`;
        }
        return `${this.host.id}-panel`;
    }

    linkAriaControl(trigger, panel) {
        if (!panel) {
            trigger.removeAttribute("aria-controls");
            return;
        }
        if ("ariaControlsElements" in trigger) {
            trigger.ariaControlsElements = [panel];
            if (trigger.ariaControlsElements?.includes(panel)) {
                return;
            }
        }
        // ID references cannot cross every Shadow DOM implementation. In that
        // case, expose the controlled menu host, which remains in the trigger's
        // document tree and owns the open state and dialog panel.
        trigger.setAttribute("aria-controls", this.host.id);
    }

    lockScroll() {
        const root = this.host.ownerDocument.documentElement;
        if (root.style.overflow !== "hidden") {
            this.previousOverflow = root.style.overflow;
            root.style.overflow = "hidden";
        }
    }

    unlockScroll() {
        const root = this.host.ownerDocument.documentElement;
        if (root.style.overflow === "hidden") {
            root.style.overflow = this.previousOverflow;
        }
    }
}

const FOCUSABLE = 'a[href], button:not([disabled]), [tabindex]:not([tabindex="-1"])';

export function trapMenuFocus(host, event, trigger) {
    const focusable = [...host.shadowRoot.querySelectorAll(FOCUSABLE), ...host.querySelectorAll(FOCUSABLE)].filter(
        (element) => element !== trigger && !element.hasAttribute("hidden"),
    );
    const first = focusable[0];
    const last = focusable.at(-1);
    const active = host.shadowRoot?.activeElement || host.ownerDocument.activeElement;
    if (!first || !last) {
        event.preventDefault();
    } else if (event.shiftKey && active === first) {
        event.preventDefault();
        last.focus();
    } else if (!event.shiftKey && active === last) {
        event.preventDefault();
        first.focus();
    }
}

{
    "default-tag": "basic-menu",
    "bloc": "./Bloc.ts",
    "editor": "./BlocEditor.ts",
    "defaultContent": "./default.html",
    "meta": {
        "title": "Menu",
        "description": "Accessible navigation overlay with an editable button trigger."
    }
}

:host {
    --_accent: var(--basic-menu-accent, var(--_tone-base));
    --_background: var(--basic-menu-background, var(--_tone-foreground));
    --_color: var(--basic-menu-color, var(--_tone-base));
    --_duration: 620ms;
    --_muted: var(--basic-menu-muted, color-mix(in srgb, var(--_color) 68%, transparent));

    display: inline-block;
    color: inherit;
    font: inherit;
    vertical-align: middle;
}

:host([hidden]) { display: none !important; }
:host([motion="snappy"]) { --_duration: 320ms; }
:host([motion="none"]) { --_duration: 1ms; }

[part="trigger-shell"] {
    display: inline-grid;
    position: relative;
    align-items: center;
    color: inherit;
}

::slotted(basic-button[slot="trigger"]) {
    color: inherit;
}

::slotted(button[slot="trigger"]) {
    min-height: 2.75rem;
    padding: .625rem 1rem;
    border: 0;
    background: transparent;
    color: inherit;
    font: inherit;
    cursor: pointer;
}

[part="layer"] {
    position: fixed;
    z-index: 100;
    inset: 0;
    visibility: hidden;
    color: var(--_color);
    font-family: var(--integration-ulvia-basic-blocs-font-body, system-ui, sans-serif);
    pointer-events: none;
    transition: visibility 0s var(--_duration);
}

:host([open]) [part="layer"] { visibility: visible; pointer-events: auto; transition-delay: 0s; }

[part="backdrop"] {
    position: absolute;
    inset: 0;
    background: #050708b8;
    opacity: 0;
    transition: opacity var(--_duration) ease;
}

:host([backdrop="blur"]) [part="backdrop"] { background: #05070880; backdrop-filter: blur(.8rem); }
:host([backdrop="none"]) [part="backdrop"] { background: transparent; }
:host([open]) [part="backdrop"] { opacity: 1; }

[part="panel"] {
    position: absolute;
    display: grid;
    grid-template-rows: auto minmax(0, 1fr) auto;
    box-sizing: border-box;
    overflow: hidden;
    background: radial-gradient(circle at 76% 16%, color-mix(in srgb, var(--_accent) 10%, transparent), transparent 26rem), var(--_background);
    color: inherit;
    outline: none;
    transition: transform var(--_duration) cubic-bezier(.76, 0, .24, 1), opacity var(--_duration) ease;
}

[part="header"],
[part="footer"] {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: clamp(1.25rem, 3vw, 2.5rem) clamp(1.25rem, 4vw, 4rem);
    gap: 1.5rem;
}

[part="close"] {
    display: flex;
    align-items: center;
    min-height: 2.75rem;
    padding: .5rem;
    border: 0;
    background: transparent;
    color: inherit;
    font: inherit;
    font-size: 1rem;
    text-transform: uppercase;
    cursor: pointer;
    gap: .75rem;
}

[part="close-icon"] { position: relative; width: 1.5rem; height: 1.5rem; }
[part="close-icon"] i { position: absolute; top: 50%; width: 100%; height: 1px; background: currentColor; }
[part="close-icon"] i:first-child { transform: rotate(45deg); }
[part="close-icon"] i:last-child { transform: rotate(-45deg); }

[part="layout"] {
    display: grid;
    grid-template-columns: minmax(18rem, .9fr) minmax(20rem, 1.1fr);
    min-height: 0;
    padding: 0 clamp(1.25rem, 4vw, 4rem);
    gap: clamp(2rem, 6vw, 7rem);
}

[part="primary"] { display: grid; align-content: center; min-width: 0; padding-block: 2rem; }
[part="eyebrow"] { margin-block-end: clamp(1.5rem, 4vh, 3rem); color: var(--_muted); }
[part="navigation"] { display: grid; align-content: center; }
[part="secondary"] { display: flex; flex-wrap: wrap; margin-block-start: 2rem; gap: .75rem 1.5rem; }
[part="media"] { min-height: 0; overflow: hidden; }
[part="details"] { display: flex; flex-wrap: wrap; color: var(--_muted); gap: .5rem 1.5rem; }
[part="footer-links"] { display: flex; flex-wrap: wrap; gap: 1.5rem; }

::slotted([slot="brand"]) { color: inherit; font-family: var(--integration-ulvia-basic-blocs-font-heading, Georgia, serif); font-size: clamp(1.25rem, 3vw, 2rem); letter-spacing: .18em; text-transform: uppercase; }
::slotted([slot="eyebrow"]),
::slotted([slot="details"]) { font-size: 1rem; }
::slotted(a) { color: inherit; font-size: 1rem; text-underline-offset: .25em; }
::slotted(a[slot="navigation"]) { display: block; width: fit-content; font-family: var(--integration-ulvia-basic-blocs-font-heading, Georgia, serif); font-size: clamp(2.5rem, 5vw, 5rem); line-height: 1.08; text-decoration: none; }
::slotted(img[slot="media"]) { display: block; width: 100%; height: 100%; object-fit: cover; }

:host([layout="links"]) [part="layout"] { grid-template-columns: minmax(0, 1fr); }
:host([layout="links"]) [part="primary"] { justify-items: center; text-align: center; }
:host([layout="links"]) [part="navigation"] { justify-items: center; }
:host([layout="links"]) [part="media"],
:host([media="hide"]) [part="media"] { display: none; }

:host([presentation="curtain"]) [part="panel"],
:host(:not([presentation])) [part="panel"] {
    inset: 0;
    transform: translateY(-100%);
}

:host([presentation="curtain"][open]) [part="panel"],
:host(:not([presentation])[open]) [part="panel"] { transform: translateY(0); }

:host([presentation="drawer"]) [part="panel"] {
    inset: 0 0 0 auto;
    width: min(92vw, 40rem);
    transform: translateX(100%);
}

:host([presentation="drawer"][open]) [part="panel"] { transform: translateX(0); }
:host([presentation="drawer"]) [part="layout"] { grid-template-columns: minmax(0, 1fr); }
:host([presentation="drawer"]) [part="primary"] { align-content: start; }
:host([presentation="drawer"]) [part="media"] { display: none; }
:host([presentation="drawer"]) ::slotted(a[slot="navigation"]) { font-size: clamp(2.25rem, 8vw, 4.5rem); }

:host([presentation="panel"]) [part="panel"] {
    inset: clamp(1rem, 5vw, 4rem);
    width: min(calc(100% - 2rem), 72rem);
    height: min(calc(100% - 2rem), 50rem);
    margin: auto;
    border: 1px solid color-mix(in srgb, var(--_color) 20%, transparent);
    opacity: 0;
    transform: translateY(1rem) scale(.97);
}

:host([presentation="panel"][open]) [part="panel"] { opacity: 1; transform: translateY(0) scale(1); }

@media (max-width: 640px) {
    [part="header"],
    [part="footer"] { padding: 1rem 1.25rem; }

    [part="header"] { min-height: 4.25rem; }
    [part="layout"] { grid-template-columns: minmax(0, 1fr); padding: 0 1.25rem; gap: 0; }
    [part="primary"] { align-content: center; padding-block: 1rem; }
    [part="eyebrow"] { margin-block-end: 1.25rem; }
    [part="navigation"] { gap: .4rem; }
    [part="secondary"] { margin-block-start: 1.5rem; gap: .75rem 1rem; }
    [part="media"] { display: none; }
    [part="footer"] { align-items: flex-end; }
    [part="details"] { display: grid; gap: .25rem; }

    ::slotted([slot="brand"]) { font-size: 1.125rem; letter-spacing: .12em; }
    ::slotted(a[slot="navigation"]) { font-size: clamp(2.25rem, 12vw, 3.75rem); }

    :host([presentation="panel"]) [part="panel"] { inset: .5rem; width: calc(100% - 1rem); height: calc(100% - 1rem); }
}

@media (prefers-reduced-motion: reduce) {
    :host { --_duration: 1ms; }
}

